414	        // ─────────────────────────────────────────────────────────────────────
415	        private static async Task SendEmailWithAttachment(string filePath)
416	        {
417	            try
418	            {
419	                Logger.Info("Sending email...");
420	
421	                string reportDate = DateTime.Now.AddDays(-1).ToString("dd-MM-yyyy");
422	                string subject = _smtpSettings.Subject.Replace("{Date}", reportDate);
423	                string htmlBody = _smtpSettings.Body.Replace("{Date}", reportDate);
424	
425	                using var mail = new MailMessage
426	                {
427	                    From = new MailAddress(
428	                                     _smtpSettings.FromEmail,
429	                                     _smtpSettings.Mail_header),
430	                    Subject = subject,
431	                    IsBodyHtml = true
432	                };
433	
434	                string logoPath = Path.Combine(
435	                    AppContext.BaseDirectory, "Assets", "Company_Logo.png");
436	
437	                if (File.Exists(logoPath))
438	                {
439	                    var htmlView = AlternateView.CreateAlternateViewFromString(
440	                        htmlBody, null, "text/html");
441	                    var logoRes = new LinkedResource(logoPath, "image/png")
442	                    { ContentId = "companylogo" };
443	                    htmlView.LinkedResources.Add(logoRes);
444	                    mail.AlternateViews.Add(htmlView);
445	                }
446	                else
447	                {
448	                    Logger.Warn("Logo not found at {0}; sending without logo", logoPath);
449	                    mail.Body = htmlBody;
450	                }
451	
452	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
453	                    mail.To.Add(to.Trim());
454	
455	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
456	                    mail.CC.Add(cc.Trim());
457	
458	                using (var fs = new FileStream(
459	                    filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
460	                {
461	                    mail.Attachments.Add(new Attachment(fs, Path.GetFileName(filePath)));
462	
463	                    using var smtp = new SmtpClient(
464	                        _smtpSettings.Host, _smtpSettings.SmtpPort)
465	                    {
466	                        Credentials = new NetworkCredential(
467	                            _smtpSettings.username, _smtpSettings.password),
468	                        EnableSsl = _smtpSettings.enableSsl
469	                    };
470	                    await smtp.SendMailAsync(mail);
471	                }
472	
473	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
474	
475	                if (File.Exists(filePath))
476	                {
477	                    File.Delete(filePath);
478	                    Logger.Info("Deleted report: {0}", filePath);
479	                }
480	            }
481	            catch (Exception ex)
482	            {
483	                Logger.Error(ex, "Email send failed");
484	            }
485	        }
